(()=>{const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const dayString=d=>d.toISOString().slice(0,10),dateTime=(b,end=false)=>(end?b.end_date:b.start_date)+'T'+((end?b.return_time:b.pickup_time)||'00:00');
function onDay(b,day){const tomorrow=dayString(new Date(Date.parse(day+'T00:00:00Z')+86400000));return dateTime(b)<tomorrow+'T00:00'&&dateTime(b,true)>day+'T00:00';}
function monthDays(month){const [year,m]=month.split('-').map(Number),first=new Date(Date.UTC(year,m-1,1)),count=new Date(Date.UTC(year,m,0)).getUTCDate();return {offset:(first.getUTCDay()+6)%7,days:Array.from({length:count},(_,i)=>month+'-'+String(i+1).padStart(2,'0'))};}
const statusLabel={requested:'Pending request',confirmed:'Accepted',completed:'Completed'};
window.GoRideCalendar={onDay,monthDays,render({month,car,day,bookings,cars,updatedAt}){const {offset,days}=monthDays(month),today=new Date(Date.now()+330*60000).toISOString().slice(0,10),monthLabel=new Date(month+'-01T00:00:00Z').toLocaleDateString('en-IN',{month:'long',year:'numeric',timeZone:'UTC'}),selected=cars.find(c=>c.id===car),agenda=bookings.filter(b=>onDay(b,day)),reserved=agenda.filter(b=>b.status!=='requested'),pending=agenda.filter(b=>b.status==='requested');return `<div class="owner-calendar"><div class="calendar-toolbar"><div><span class="kicker">PLAN THE MONTH</span><h2>${esc(monthLabel)}</h2></div><div class="calendar-month-controls"><button type="button" class="secondary" data-calendar-shift="-1" aria-label="Previous month">←</button><label>Month<input id="calendar-month" type="month" value="${esc(month)}" min="2000-01" max="2099-12"></label><button type="button" class="secondary" data-calendar-shift="1" aria-label="Next month">→</button><button type="button" class="secondary" data-calendar-today>Today</button></div></div><div class="calendar-filter"><label>Car listing<select id="calendar-car"><option value="">All cars</option>${cars.map(c=>`<option value="${esc(c.id)}" ${car===c.id?'selected':''}>${esc(c.name)} · ${esc(c.id.slice(0,8))}${c.status==='maintenance'?' · Maintenance':c.status==='hidden'?' · Hidden':''}</option>`).join('')}</select></label><p>Each listing represents one physical car. All times are IST.${selected?.status==='maintenance'?' <strong>This car is marked under maintenance.</strong>':''}${selected?.status==='hidden'?' <strong>This car is hidden from customer searches.</strong>':''}</p></div><div class="calendar-legend"><span><i class="reserved-dot"></i>Accepted / completed</span><span><i class="pending-dot"></i>Pending · does not reserve</span></div><p class="calendar-help">Select a day to see exact pick-up and return times. A day marked reserved may still have free hours. No accepted booking does not guarantee availability; check the car’s listing status and owner arrangements.</p><div class="calendar-grid" role="group" aria-label="${esc(monthLabel)} booking calendar">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<span class="calendar-weekday">${d}</span>`).join('')}${Array.from({length:offset},()=>'<span class="calendar-blank" aria-hidden="true"></span>').join('')}${days.map(date=>{const list=bookings.filter(b=>onDay(b,date)),accepted=list.filter(b=>b.status!=='requested').length,requests=list.length-accepted;return `<button type="button" class="calendar-day ${date===day?'calendar-selected':''} ${date===today?'calendar-current':''} ${accepted?'calendar-reserved':''}" data-calendar-day="${date}" aria-pressed="${date===day}" aria-label="${date}, ${accepted} reserved, ${requests} pending"><strong>${Number(date.slice(-2))}</strong>${accepted?`<span class="calendar-reserved-count">${accepted} reserved</span>`:''}${requests?`<span class="calendar-pending-count">${requests} pending</span>`:''}${!list.length?'<span class="calendar-no-booking">—</span>':''}</button>`;}).join('')}</div><div class="calendar-agenda"><div class="calendar-agenda-heading"><h3>${esc(new Date(day+'T00:00:00Z').toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'long',timeZone:'UTC'}))}</h3><span>${reserved.length} reserved · ${pending.length} pending</span></div>${agenda.length?agenda.map(b=>`<article class="calendar-booking"><div><h4>${esc(b.car_name)}</h4><span class="calendar-status ${b.status==='requested'?'calendar-status-pending':''}">${esc(statusLabel[b.status]||b.status)}</span></div><p>${esc(b.location)} · ${b.mode==='self'?'Self-drive':'Chauffeur'} · Listing ${esc(b.car_id.slice(0,8))}</p><dl><div><dt>Pick-up · IST</dt><dd>${esc(b.start_date)} · ${esc(b.pickup_time||'Time not recorded')}</dd></div><div><dt>Return · IST</dt><dd>${esc(b.end_date)} · ${esc(b.return_time||'Time not recorded')}</dd></div></dl><p>${esc(b.name)} · Booking ${esc(b.id.slice(0,8))}</p>${!b.pickup_time||!b.return_time?'<p class="calendar-help">Legacy booking: midnight boundaries are used for date availability checks. Confirm the actual times with the customer.</p>':''}</article>`).join(''):'<div class="calendar-empty"><strong>No bookings on this day</strong><p>Check the car listing and owner arrangements before confirming availability.</p></div>'}</div><p class="calendar-updated">Updated ${esc(new Date(updatedAt).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'}))} IST · Manage requests in Bookings &amp; customers.</p></div>`;}};
})();
